display Integer durationDisp()
{
    Integer res;
    ;
    if (this.EndDateTime && this.StartDateTime)
    {
        res = any2int(DateTimeUtil::getDifference(this.EndDateTime, this.StartDateTime));
    }
    return res;
}

private int aggregatedDocumentCount()
{
    METBatchMonitoringLog child;
    ;
    if (!this.BatchJobId || !this.BatchTaskId)
    {
        return 0;
    }
    select sum(DocumentCount) from child
        where child.BatchJobId  == this.BatchJobId
           && child.BatchTaskId != this.BatchTaskId
           && child.BatchTaskId != 0;
    return any2int(child.DocumentCount);
}

private boolean isHeaderWithChildren()
{
    METBatchMonitoringLog child;
    ;
    if (!this.BatchJobId || !this.BatchTaskId)
    {
        return false;
    }
    select firstonly RecId from child
        where child.BatchJobId  == this.BatchJobId
           && child.BatchTaskId != this.BatchTaskId
           && child.BatchTaskId != 0;
    return child.RecId != 0;
}

private boolean allChildrenCompleted()
{
    METBatchMonitoringLog child;
    ;
    if (!this.BatchJobId || !this.BatchTaskId)
    {
        return true;
    }
    select firstonly RecId from child
        where child.BatchJobId  == this.BatchJobId
           && child.BatchTaskId != this.BatchTaskId
           && child.BatchTaskId != 0
           && child.Status == METBatchMonitoringStatus::Running;
    return child.RecId == 0;
}

display Integer remainingDisp()
{
    int docCount = this.isHeaderWithChildren() ? this.aggregatedDocumentCount() : this.DocumentCount;
    ;
    return max(0, this.LinesToProcess - docCount);
}

display Integer percentCompleteDisp()
{
    int docCount = this.isHeaderWithChildren() ? this.aggregatedDocumentCount() : this.DocumentCount;
    ;
    return this.LinesToProcess > 0 ? (docCount * 100 / this.LinesToProcess) : 0;
}

display Integer elapsedDisp()
{
    UtcDateTime endDt;
    ;
    if (!this.StartDateTime)
    {
        return 0;
    }
    endDt = this.EndDateTime ? this.EndDateTime : DateTimeUtil::getSystemDateTime();
    return any2int(DateTimeUtil::getDifference(endDt, this.StartDateTime));
}

display Integer estimatedRemainingDisp()
{
    Integer     elapsedSec, remaining;
    int         docCount;
    boolean     isComplete;
    UtcDateTime endDt;
    ;
    if (!this.StartDateTime || this.LinesToProcess <= 0)
    {
        return 0;
    }

    if (this.isHeaderWithChildren())
    {
        // For multi-thread header rows: aggregate progress from child task records.
        // No isComplete check -- the formula naturally returns 0 when remaining = 0.
        docCount = this.aggregatedDocumentCount();
        if (docCount <= 0)
        {
            return 0;
        }
        endDt      = DateTimeUtil::getSystemDateTime();
        elapsedSec = any2int(DateTimeUtil::getDifference(endDt, this.StartDateTime));
        remaining  = max(0, this.LinesToProcess - docCount);
        return (remaining * elapsedSec) / docCount;
    }
    else
    {
        docCount   = this.DocumentCount;
        isComplete = this.Status == METBatchMonitoringStatus::Completed;
        endDt = this.EndDateTime ? this.EndDateTime : DateTimeUtil::getSystemDateTime();
    }

    if (docCount <= 0 || isComplete)
    {
        return 0;
    }

    elapsedSec = any2int(DateTimeUtil::getDifference(endDt, this.StartDateTime));
    remaining  = max(0, this.LinesToProcess - docCount);
    return (remaining * elapsedSec) / docCount;
}

/// <summary>
/// Populates SessionId and SessionLoginDateTime from the current session.
/// Follows the master session when running inside a child session.
/// </summary>
public void setSession()
{
    xSession xSession = new xSession(sessionid());

    this.SessionId            = xSession.sessionId();
    this.SessionLoginDateTime = xSession.loginDateTime();
}

display NoYes isSessionActive()
{
    return Global::isSessionActive(this.SessionId, this.SessionLoginDateTime);
}

static void clearLog(int _daysToKeep = 0)
{
    METBatchMonitoringLog  batchMonitoringLog;
    TransDateTime          delDate = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1 * _daysToKeep);
    ;
    if (! _daysToKeep)
    {
        delete_from batchMonitoringLog;
    }
    else
    {
        delete_from batchMonitoringLog
            where batchMonitoringLog.createdDateTime < delDate;
    }
}
